    public static void main(String[] args) {
        Koleksi[] r = { new Buku(), new Majalah() };
        int n = 0;
        for (Koleksi k : r) {
            if (k instanceof Pinjam) n++;
        }
        System.out.println(n);
    }
}

interface Pinjam {}
abstract class Koleksi {}
class Buku extends Koleksi implements Pinjam {}
class Majalah extends Koleksi {}

