cards.solution:
public class Main {
    public static void main(String[] args) {
        DVD d = new DVD("Interstellar", 169);
        d.info();
    }
}

abstract class Koleksi {
    private String judul;

    Koleksi(String judul) {
        this.judul = judul;
    }

    String getJudul() {
        return judul;
    }

    abstract void info();
}

class DVD extends Koleksi {
    private int durasi;

    DVD(String judul, int durasi) {
        super(judul);
        this.durasi = durasi;
    }

    @Override
    void info() {
        System.out.println("DVD: " + getJudul() + " (" + durasi + " menit)");
    }
}

